import{_ as e,o,c as a,a as r}from"./app.DLiRGumz.js";const u=JSON.parse('{"title":"Thegent 2026 Polyglot WBS & Workstream Assignment","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/POLYGLOT_WBS_2026.md","filePath":"architecture/POLYGLOT_WBS_2026.md","lastUpdated":1771574377000}'),n={name:"architecture/POLYGLOT_WBS_2026.md"};function i(s,t,l,d,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="thegent-2026-polyglot-wbs-workstream-assignment" tabindex="-1">Thegent 2026 Polyglot WBS &amp; Workstream Assignment <a class="header-anchor" href="#thegent-2026-polyglot-wbs-workstream-assignment" aria-label="Permalink to &quot;Thegent 2026 Polyglot WBS &amp; Workstream Assignment&quot;">​</a></h1><p>This document defines the Phased Work Breakdown Structure (WBS) for the <code>thegent</code> polyglot migration, assigning specific tasks to language-specialized workstreams.</p><hr><h2 id="_1-workstreams-defined" tabindex="-1">1. Workstreams Defined <a class="header-anchor" href="#_1-workstreams-defined" aria-label="Permalink to &quot;1. Workstreams Defined&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Stream</th><th style="text-align:left;">Focus</th><th style="text-align:left;">Primary Toolchain</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>[NATIVE]</strong></td><td style="text-align:left;">Shared Memory, Rust Extensions, Wasm Host</td><td style="text-align:left;"><code>cargo</code>, <code>zig</code>, <code>rustc</code></td></tr><tr><td style="text-align:left;"><strong>[NET]</strong></td><td style="text-align:left;">High-throughput Proxying, API Interop</td><td style="text-align:left;"><code>go</code>, <code>cgo</code></td></tr><tr><td style="text-align:left;"><strong>[LOGIC]</strong></td><td style="text-align:left;">Orchestration, Heuristics, Mojo Acceleration</td><td style="text-align:left;"><code>uv</code>, <code>pypy</code>, <code>mojo</code></td></tr><tr><td style="text-align:left;"><strong>[INFRA]</strong></td><td style="text-align:left;">Build Systems, CI/CD, Telemetry, IPC</td><td style="text-align:left;"><code>task</code>, <code>docker</code>, <code>otel</code></td></tr></tbody></table><hr><h2 id="_2-phase-1-the-atomic-foundation-months-1–2" tabindex="-1">2. Phase 1: The &quot;Atomic&quot; Foundation (Months 1–2) <a class="header-anchor" href="#_2-phase-1-the-atomic-foundation-months-1–2" aria-label="Permalink to &quot;2. Phase 1: The &quot;Atomic&quot; Foundation (Months 1–2)&quot;">​</a></h2><p><strong>Goal</strong>: Replace slow file-based IPC with high-speed memory-mapped shared state.</p><h3 id="native" tabindex="-1">[NATIVE] <a class="header-anchor" href="#native" aria-label="Permalink to &quot;[NATIVE]&quot;">​</a></h3><ul><li><strong>ID: N1.1</strong> | Develop <code>thegent-shm</code> Rust crate. Define memory-mapped structs for provider health, quotas, and circuit breakers.</li><li><strong>ID: N1.2</strong> | Implement <code>thegent-ipc</code> crate. Wrap <code>nng</code> or <code>iceoryx2</code> for high-speed cross-process messaging.</li><li><strong>ID: N1.3</strong> | Create C-ABI exports for SHM pointers to allow Go/Mojo access.</li></ul><h3 id="net" tabindex="-1">[NET] <a class="header-anchor" href="#net" aria-label="Permalink to &quot;[NET]&quot;">​</a></h3><ul><li><strong>ID: G1.1</strong> | Integrate <code>mmap-go</code> into <code>cliproxyapi-plusplus</code>. Allow the Go proxy to write usage metrics directly to Rust-managed SHM.</li><li><strong>ID: G1.2</strong> | Standardize JSON-RPC control plane in Go for Python-to-Go signaling (e.g., refreshing specific provider configs).</li></ul><h3 id="logic" tabindex="-1">[LOGIC] <a class="header-anchor" href="#logic" aria-label="Permalink to &quot;[LOGIC]&quot;">​</a></h3><ul><li><strong>ID: L1.1</strong> | Integrate <code>thegent-shm-python</code> bindings into the orchestrator.</li><li><strong>ID: L1.2</strong> | Migrate <code>MaildirQueue</code> calls in <code>multi_runtime_bridge.py</code> to <code>thegent-ipc</code>.</li></ul><h3 id="infra" tabindex="-1">[INFRA] <a class="header-anchor" href="#infra" aria-label="Permalink to &quot;[INFRA]&quot;">​</a></h3><ul><li><strong>ID: I1.1</strong> | Unified <code>Taskfile.yml</code> implementation for <code>cargo</code>, <code>go</code>, and <code>uv</code>.</li><li><strong>ID: I1.2</strong> | Implement <code>thegent doctor --shm</code> to verify cross-language memory access and permissions.</li></ul><hr><h2 id="_3-phase-2-compute-acceleration-months-3–4" tabindex="-1">3. Phase 2: Compute Acceleration (Months 3–4) <a class="header-anchor" href="#_3-phase-2-compute-acceleration-months-3–4" aria-label="Permalink to &quot;3. Phase 2: Compute Acceleration (Months 3–4)&quot;">​</a></h2><p><strong>Goal</strong>: Offload &quot;hot&quot; Python logic to Mojo and Rust for 10x throughput.</p><h3 id="native-1" tabindex="-1">[NATIVE] <a class="header-anchor" href="#native-1" aria-label="Permalink to &quot;[NATIVE]&quot;">​</a></h3><ul><li><strong>ID: N2.1</strong> | Refactor <code>ParetoRouter</code> (Rust) for zero-copy access to the SHM health matrix.</li><li><strong>ID: N2.2</strong> | Implement <code>AtomicDecisionEngine</code> in Rust for fast-path routing (bypass Python for cached routes).</li></ul><h3 id="logic-1" tabindex="-1">[LOGIC] <a class="header-anchor" href="#logic-1" aria-label="Permalink to &quot;[LOGIC]&quot;">​</a></h3><ul><li><strong>ID: L2.1</strong> | Mojo Environment Setup: Integrate Mojo toolchain with <code>uv</code> project structure.</li><li><strong>ID: L2.2</strong> | Offload <code>HeuristicOptimizer</code> and <code>AgentScorer</code> logic to Mojo <code>@mojo</code> functions.</li><li><strong>ID: L2.3</strong> | Implement Mojo-to-Python bridge for seamless logic swapping.</li></ul><h3 id="infra-1" tabindex="-1">[INFRA] <a class="header-anchor" href="#infra-1" aria-label="Permalink to &quot;[INFRA]&quot;">​</a></h3><ul><li><strong>ID: I2.1</strong> | Cross-language Telemetry: Implement OTLP spans for Python -&gt; Mojo -&gt; Rust calls.</li><li><strong>ID: I2.2</strong> | Automated benchmarks: CI/CD path to verify Mojo speedups vs. PyPy baseline.</li></ul><hr><h2 id="_4-phase-3-the-atomic-tool-sandbox-months-5–6" tabindex="-1">4. Phase 3: The &quot;Atomic Tool&quot; Sandbox (Months 5–6) <a class="header-anchor" href="#_4-phase-3-the-atomic-tool-sandbox-months-5–6" aria-label="Permalink to &quot;4. Phase 3: The &quot;Atomic Tool&quot; Sandbox (Months 5–6)&quot;">​</a></h2><p><strong>Goal</strong>: Standardize and sandbox high-performance agent tools in Zig/Wasm.</p><h3 id="native-2" tabindex="-1">[NATIVE] <a class="header-anchor" href="#native-2" aria-label="Permalink to &quot;[NATIVE]&quot;">​</a></h3><ul><li><strong>ID: N3.1</strong> | Implement <code>thegent-wasm-host</code> using Extism. Integrate with Python and Go.</li><li><strong>ID: N3.2</strong> | Develop Zig SDK for &quot;Atomic Tools&quot; (minimal binary size, &lt;100kb).</li><li><strong>ID: N3.3</strong> | Build Rust-to-Wasm bridge for heavy compute tools.</li></ul><h3 id="logic-2" tabindex="-1">[LOGIC] <a class="header-anchor" href="#logic-2" aria-label="Permalink to &quot;[LOGIC]&quot;">​</a></h3><ul><li><strong>ID: L3.1</strong> | Standardize <code>thegent</code> Tool Interface for Wasm. Define the memory-passing contract.</li><li><strong>ID: L3.2</strong> | Migrate core tools (File Search, Regex, Token Counting) to Zig/Wasm.</li></ul><h3 id="infra-2" tabindex="-1">[INFRA] <a class="header-anchor" href="#infra-2" aria-label="Permalink to &quot;[INFRA]&quot;">​</a></h3><ul><li><strong>ID: I3.1</strong> | Build <code>thegent-registry-wasm</code>: A central store for compiled .wasm tool assets.</li><li><strong>ID: I3.2</strong> | Implement Wasm sandboxing security policies (limited FS/Net access).</li></ul><hr><h2 id="_5-phase-4-production-maturity-months-7" tabindex="-1">5. Phase 4: Production Maturity (Months 7+) <a class="header-anchor" href="#_5-phase-4-production-maturity-months-7" aria-label="Permalink to &quot;5. Phase 4: Production Maturity (Months 7+)&quot;">​</a></h2><p><strong>Goal</strong>: Unified management and 99.99% reliability across all runtimes.</p><h3 id="net-1" tabindex="-1">[NET] <a class="header-anchor" href="#net-1" aria-label="Permalink to &quot;[NET]&quot;">​</a></h3><ul><li><strong>ID: G4.1</strong> | High-availability (HA) Go Proxy: Implement cluster-aware state sharing using SHM-over-Network.</li></ul><h3 id="logic-3" tabindex="-1">[LOGIC] <a class="header-anchor" href="#logic-3" aria-label="Permalink to &quot;[LOGIC]&quot;">​</a></h3><ul><li><strong>ID: L4.1</strong> | Self-Healing Orchestrator: Python logic to restart crashed Go/Rust/Mojo workers using the SHM heartbeat.</li></ul><h3 id="infra-3" tabindex="-1">[INFRA] <a class="header-anchor" href="#infra-3" aria-label="Permalink to &quot;[INFRA]&quot;">​</a></h3><ul><li><strong>ID: I4.1</strong> | Unified CLI: <code>thegent run ...</code> handles all polyglot compilation and deployment transparently.</li><li><strong>ID: I4.2</strong> | Global Performance Matrix: Real-time dashboard showing throughput per language (Python vs. Rust vs. Go).</li></ul>',43)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
